using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json.Nodes;
using Arch.Core;
using Ludots.Core.Engine;
using Ludots.Core.Persistence;
using Ludots.Core.Scripting;
using Ludots.Platform.Abstractions;
using MessagePack;
using MessagePack.Formatters;
using MessagePack.Resolvers;

namespace Ludots.AgentBridge.Tools
{
    /// <summary>
    /// Save/load bridge tools. All state flows through the formal pipeline: slots via
    /// SaveSlotStore over the engine ISaveStorage service, capture/restore via
    /// WorldSnapshotService/WorldRestoreService at the clean tick boundary. World digests
    /// serialize through a canonicalized throwaway world (entity WorldIds normalized to 0)
    /// so hashes compare across engine processes.
    /// </summary>
    public sealed class SaveSlotsTool : IAgentTool
    {
        public string Name => "ludots.save.slots";
        public string Description => "List save slots with header metadata (kind, name, tick, mapId, createdUtc, schemaVersion, byte size). Optional 'kind' filter (manual|autosave).";
        public JsonObject? InputSchema => new JsonObject
        {
            ["type"] = "object",
            ["properties"] = new JsonObject
            {
                ["kind"] = new JsonObject { ["type"] = "string", ["description"] = "Optional slot kind filter: manual | autosave." },
            },
        };

        public JsonNode? Execute(JsonObject? args, AgentToolContext context)
        {
            SaveSlotStore store = SaveToolSupport.RequireSlotStore(context.Engine);
            string? kind = SaveToolSupport.OptionalString(args, "kind");
            var slots = new JsonArray();
            foreach (SaveSlotHeader header in store.ListSlots())
            {
                if (kind != null && !string.Equals(header.Id.Kind, kind, StringComparison.Ordinal))
                {
                    continue;
                }

                slots.Add(new JsonObject
                {
                    ["kind"] = header.Id.Kind,
                    ["name"] = header.Id.Name,
                    ["slot"] = header.Id.Value,
                    ["tick"] = header.Header.Tick,
                    ["mapId"] = header.Header.MapId,
                    ["createdUtc"] = header.Header.CreatedUtc.ToString("o"),
                    ["schemaVersion"] = header.Header.SchemaVersion,
                    ["bytes"] = SaveToolSupport.SlotByteSize(context.Engine, header.Id),
                });
            }

            return new JsonObject
            {
                ["slots"] = slots,
                ["count"] = slots.Count,
            };
        }
    }

    public sealed class SaveCaptureTool : IAgentTool
    {
        public string Name => "ludots.save.capture";
        public string Description => "Capture an in-memory world snapshot at the clean tick boundary without writing a slot. Returns tick and normalized world digest. No parameters.";
        public JsonObject? InputSchema => null;

        public JsonNode? Execute(JsonObject? args, AgentToolContext context)
        {
            var snapshotService = new WorldSnapshotService();
            WorldSaveSnapshot snapshot = SaveToolSupport.Capture(context.Engine, snapshotService);
            return new JsonObject
            {
                ["tick"] = snapshot.Header.Tick,
                ["mapId"] = snapshot.Header.MapId,
                ["worldBytes"] = snapshot.WorldBytes.Length,
                ["worldDigest"] = SaveToolSupport.ComputeWorldDigest(context.Engine, snapshot),
            };
        }
    }

    public sealed class SaveWriteTool : IAgentTool
    {
        public string Name => "ludots.save.write";
        public string Description => "Capture at the clean tick boundary and write a real disk slot (atomic temp+commit via engine ISaveStorage). 'name' defaults to 'agent-<utc timestamp>'; 'kind' defaults to manual.";
        public JsonObject? InputSchema => new JsonObject
        {
            ["type"] = "object",
            ["properties"] = new JsonObject
            {
                ["name"] = new JsonObject { ["type"] = "string", ["description"] = "Slot name token [a-zA-Z0-9-_]; defaults to agent-<utc>." },
                ["kind"] = new JsonObject { ["type"] = "string", ["description"] = "manual | autosave; defaults to manual." },
            },
        };

        public JsonNode? Execute(JsonObject? args, AgentToolContext context)
        {
            SaveSlotStore store = SaveToolSupport.RequireSlotStore(context.Engine);
            string name = SaveToolSupport.OptionalString(args, "name") ?? $"agent-{DateTime.UtcNow:yyyyMMdd-HHmmss}";
            string kind = SaveToolSupport.OptionalString(args, "kind") ?? "manual";
            SaveSlotId id = SaveToolSupport.ResolveSlotId(name, kind);

            WorldSaveSnapshot snapshot = SaveToolSupport.Capture(context.Engine, new WorldSnapshotService());
            try
            {
                store.WriteSlot(id, snapshot);
            }
            catch (SaveContextException ex)
            {
                throw new AgentToolException(AgentBridgeErrorCodes.ToolFailed, $"Write slot '{id.Value}' failed: {ex.Message}");
            }

            return new JsonObject
            {
                ["slot"] = id.Value,
                ["kind"] = id.Kind,
                ["name"] = id.Name,
                ["tick"] = snapshot.Header.Tick,
                ["bytes"] = SaveToolSupport.SlotByteSize(context.Engine, id),
                ["worldDigest"] = SaveToolSupport.ComputeWorldDigest(context.Engine, snapshot),
            };
        }
    }

    public sealed class SaveReadTool : IAgentTool
    {
        public string Name => "ludots.save.read";
        public string Description => "Read a slot from disk (section hashes verified) without restoring. Requires 'name'; optional 'kind' defaults to manual. Returns header metadata and normalized world digest.";
        public JsonObject? InputSchema => new JsonObject
        {
            ["type"] = "object",
            ["properties"] = new JsonObject
            {
                ["name"] = new JsonObject { ["type"] = "string" },
                ["kind"] = new JsonObject { ["type"] = "string", ["description"] = "manual | autosave; defaults to manual." },
            },
            ["required"] = new JsonArray { "name" },
        };

        public JsonNode? Execute(JsonObject? args, AgentToolContext context)
        {
            SaveSlotStore store = SaveToolSupport.RequireSlotStore(context.Engine);
            SaveSlotId id = SaveToolSupport.RequireSlotId(args);
            WorldSaveSnapshot snapshot = SaveToolSupport.ReadSlot(store, id);
            return new JsonObject
            {
                ["slot"] = id.Value,
                ["tick"] = snapshot.Header.Tick,
                ["mapId"] = snapshot.Header.MapId,
                ["createdUtc"] = snapshot.Header.CreatedUtc.ToString("o"),
                ["schemaVersion"] = snapshot.Header.SchemaVersion,
                ["bytes"] = SaveToolSupport.SlotByteSize(context.Engine, id),
                ["worldDigest"] = SaveToolSupport.ComputeWorldDigest(context.Engine, snapshot),
            };
        }
    }

    public sealed class SaveRestoreTool : IAgentTool
    {
        public string Name => "ludots.save.restore";
        public string Description => "Read a slot from disk and restore it into the running world (header gates verified). Requires 'name'; optional 'kind' defaults to manual. Returns restored tick and post-restore normalized world digest.";
        public JsonObject? InputSchema => new JsonObject
        {
            ["type"] = "object",
            ["properties"] = new JsonObject
            {
                ["name"] = new JsonObject { ["type"] = "string" },
                ["kind"] = new JsonObject { ["type"] = "string", ["description"] = "manual | autosave; defaults to manual." },
            },
            ["required"] = new JsonArray { "name" },
        };

        public JsonNode? Execute(JsonObject? args, AgentToolContext context)
        {
            SaveSlotStore store = SaveToolSupport.RequireSlotStore(context.Engine);
            SaveSlotId id = SaveToolSupport.RequireSlotId(args);
            WorldSaveSnapshot snapshot = SaveToolSupport.ReadSlot(store, id);
            try
            {
                new WorldRestoreService().Restore(context.Engine, snapshot);
            }
            catch (SaveContextException ex)
            {
                throw new AgentToolException(AgentBridgeErrorCodes.ToolFailed, $"Restore slot '{id.Value}' failed: {ex.Message}");
            }
            return new JsonObject
            {
                ["slot"] = id.Value,
                ["restoredTick"] = context.Engine.GameSession.CurrentTick,
                ["worldDigest"] = SaveToolSupport.ComputeWorldDigest(context.Engine, new WorldSnapshotService()),
            };
        }
    }

    internal static class SaveToolSupport
    {
        public static SaveSlotStore RequireSlotStore(GameEngine engine)
        {
            if (!engine.TryGetService(CoreServiceKeys.SaveStorage, out ISaveStorage? storage) || storage == null)
            {
                throw new AgentToolException(
                    AgentBridgeErrorCodes.ServiceUnavailable,
                    "Engine save storage service is not available; the host did not provide ISaveStorage.");
            }

            return new SaveSlotStore(storage);
        }

        public static WorldSaveSnapshot ReadSlot(SaveSlotStore store, SaveSlotId id)
        {
            try
            {
                return store.ReadSlot(id);
            }
            catch (SaveContextException ex)
            {
                throw new AgentToolException(AgentBridgeErrorCodes.ToolFailed, $"Read slot '{id.Value}' failed: {ex.Message}");
            }
        }

        public static WorldSaveSnapshot Capture(GameEngine engine, WorldSnapshotService snapshots)
        {
            try
            {
                return snapshots.Capture(engine, SaveSnapshotBoundary.CleanAfter(SystemGroup.ClearPresentationFlags));
            }
            catch (SaveContextException ex)
            {
                throw new AgentToolException(AgentBridgeErrorCodes.ToolFailed, $"Capture failed: {ex.Message}");
            }
        }

        public static SaveSlotId RequireSlotId(JsonObject? args)
        {
            string name = OptionalString(args, "name") ?? throw new AgentToolException(
                AgentBridgeErrorCodes.InvalidParams,
                "Parameter 'name' is required.");
            string kind = OptionalString(args, "kind") ?? "manual";
            return ResolveSlotId(name, kind);
        }

        public static SaveSlotId ResolveSlotId(string name, string kind)
        {
            if (!string.Equals(kind, "manual", StringComparison.Ordinal) &&
                !string.Equals(kind, "autosave", StringComparison.Ordinal))
            {
                throw new AgentToolException(
                    AgentBridgeErrorCodes.InvalidParams,
                    $"Unknown slot kind '{kind}'. Expected manual | autosave.");
            }

            var id = new SaveSlotId(kind, name);
            try
            {
                _ = id.ToStorageKey();
                return id;
            }
            catch (SaveContextException ex)
            {
                throw new AgentToolException(AgentBridgeErrorCodes.InvalidParams, ex.Message);
            }
        }

        public static string? OptionalString(JsonObject? args, string key)
        {
            JsonNode? node = args?[key];
            return node is null ? null : node.GetValue<string>();
        }

        public static int SlotByteSize(GameEngine engine, SaveSlotId id)
        {
            if (!engine.TryGetService(CoreServiceKeys.SaveStorage, out ISaveStorage? storage) || storage == null)
            {
                return 0;
            }

            string key = id.ToStorageKey();
            return storage.Exists(key) ? storage.ReadAllBytes(key).Length : 0;
        }

        public static string ComputeWorldDigest(GameEngine engine, WorldSnapshotService snapshots)
        {
            return ComputeWorldDigest(engine, Capture(engine, snapshots));
        }

        public static string ComputeWorldDigest(GameEngine engine, WorldSaveSnapshot snapshot)
        {
            LudotsBinaryWorldSerializer serializer = LudotsPersistenceSerializerFactory.Create(engine);
            using World canonical = serializer.Deserialize(snapshot.WorldBytes);
            SaveEntityWorldIdNormalizer.Normalize(canonical, canonicalWorldId: 0);
            return HashWorld(canonical);
        }

        // World blob bytes are not stable across serialize invocations (chunk/type ordering
        // varies), so the digest hashes the sorted per-entity/per-component row dump instead —
        // the same lens SaveContinuationTrace uses for cross-instance determinism comparison.
        private static string HashWorld(World world)
        {
            MessagePackSerializerOptions options = MessagePackSerializerOptions.Standard.WithResolver(
                CompositeResolver.Create(
                    LudotsCorePersistenceFormatters.CreateFormatters(),
                    new IFormatterResolver[]
                    {
                        BuiltinResolver.Instance,
                        ContractlessStandardResolverAllowPrivate.Instance
                    }));

            var rows = new List<string>();
            world.Query(in QueryDescription.Null, entity =>
            {
                Signature signature = world.GetSignature(entity);
                var componentRows = new List<string>(signature.Components.Length);
                foreach (ComponentType componentType in signature.Components)
                {
                    Type type = componentType.Type;
                    object? component = world.Get(entity, componentType);
                    componentRows.Add(component == null
                        ? $"{type.FullName ?? type.Name}=<null>"
                        : $"{type.FullName ?? type.Name}={Convert.ToHexString(MessagePackSerializer.Serialize(type, component, options))}");
                }

                componentRows.Sort(StringComparer.Ordinal);
                rows.Add($"{entity.Id}:{entity.Version}|{string.Join("|", componentRows)}");
            });

            rows.Sort(StringComparer.Ordinal);
            return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(string.Join("\n", rows))));
        }
    }
}

using System.IO;
using System.Text.Json.Nodes;
using Ludots.AgentBridge;
using Ludots.AgentBridge.Tools;
using Ludots.Core.Engine;
using Ludots.Core.Persistence;
using Ludots.Core.Scripting;
using Ludots.Platform.Abstractions;
using Ludots.Platform.Desktop;
using Ludots.Tests;
using NUnit.Framework;

namespace Ludots.Tests.Gas
{
    /// <summary>
    /// Save bridge tool contracts: every tool drives the formal pipeline (SaveSlotStore over
    /// engine ISaveStorage, clean-boundary capture, WorldRestoreService restore) and the
    /// normalized world digest is stable across engine instances for identical state.
    /// </summary>
    public sealed class SaveToolsContractTests
    {
        private string _root = null!;
        private GameEngine _engine = null!;
        private AgentToolContext _context = null!;

        [SetUp]
        public void SetUp()
        {
            _root = Path.Combine(Path.GetTempPath(), "ludots-save-tools-" + Path.GetRandomFileName());
            Directory.CreateDirectory(_root);
            _engine = CreateEngine(_root);
            UseTurnBasedPacemaker(_engine);
            _context = new AgentToolContext(_engine);
        }

        [TearDown]
        public void TearDown()
        {
            _engine.Dispose();
            if (Directory.Exists(_root))
            {
                Directory.Delete(_root, recursive: true);
            }
        }

        [Test]
        public void WriteSlotsReadRestore_RoundTripAcrossEngineInstances()
        {
            var write = new SaveWriteTool();
            JsonObject result = write.ExecuteObject(
                new JsonObject { ["name"] = "contract-a" },
                _context)!;
            Assert.That(result["slot"]!.GetValue<string>(), Is.EqualTo("manual/contract-a"));
            string savedDigest = result["worldDigest"]!.GetValue<string>();
            int savedTick = result["tick"]!.GetValue<int>();
            Assert.That(savedTick, Is.GreaterThan(0));

            var slots = new SaveSlotsTool();
            JsonObject listing = slots.ExecuteObject(null, _context);
            Assert.That(listing["count"]!.GetValue<int>(), Is.GreaterThanOrEqualTo(1));
            JsonObject? entry = FindSlot(listing, "manual/contract-a");
            Assert.That(entry, Is.Not.Null);
            Assert.That(entry!["tick"]!.GetValue<int>(), Is.EqualTo(savedTick));
            Assert.That(entry["bytes"]!.GetValue<int>(), Is.GreaterThan(0));

            var read = new SaveReadTool();
            JsonObject readResult = read.ExecuteObject(
                new JsonObject { ["name"] = "contract-a" },
                _context)!;
            Assert.That(readResult["worldDigest"]!.GetValue<string>(), Is.EqualTo(savedDigest));

            using GameEngine second = CreateEngine(_root);
            var secondContext = new AgentToolContext(second);
            var restore = new SaveRestoreTool();
            JsonObject restored = restore.ExecuteObject(
                new JsonObject { ["name"] = "contract-a" },
                secondContext)!;
            Assert.That(restored["restoredTick"]!.GetValue<int>(), Is.EqualTo(savedTick));
            Assert.That(
                restored["worldDigest"]!.GetValue<string>(),
                Is.EqualTo(savedDigest),
                "normalized digest must be identical in a different engine instance after restore");
        }

        [Test]
        public void CaptureWithoutWrite_DoesNotCreateSlots()
        {
            var capture = new SaveCaptureTool();
            JsonObject result = capture.ExecuteObject(null, _context);

            Assert.That(result["tick"]!.GetValue<int>(), Is.GreaterThan(0));
            Assert.That(result["worldDigest"]!.GetValue<string>(), Is.Not.Null);
            JsonObject listing = new SaveSlotsTool().ExecuteObject(null, _context);
            Assert.That(listing["count"]!.GetValue<int>(), Is.EqualTo(0));
        }

        [Test]
        public void RestoreOfTamperedSlot_FailsWithReadableError()
        {
            new SaveWriteTool().ExecuteObject(new JsonObject { ["name"] = "tampered" }, _context);
            CorruptSlotBytes("manual/tampered");

            AgentToolException ex = Assert.Throws<AgentToolException>(() =>
                new SaveReadTool().ExecuteObject(new JsonObject { ["name"] = "tampered" }, _context));
            Assert.That(ex!.Message, Does.Contain("tampered"));
        }

        [Test]
        public void MissingStorageService_FailsClosed()
        {
            using var bare = CreateInitializedEngineWithoutStorage();
            var bareContext = new AgentToolContext(bare);

            AgentToolException ex = Assert.Throws<AgentToolException>(() =>
                new SaveSlotsTool().ExecuteObject(null, bareContext));
            Assert.That(ex!.Code, Is.EqualTo("service.unavailable"));
        }

        [Test]
        public void InvalidSlotKind_IsRejected()
        {
            AgentToolException ex = Assert.Throws<AgentToolException>(() =>
                new SaveWriteTool().ExecuteObject(
                    new JsonObject { ["name"] = "x", ["kind"] = "cloud" },
                    _context));
            Assert.That(ex!.Code, Is.EqualTo("invalid.params"));
        }

        private static JsonObject? FindSlot(JsonObject listing, string slot)
        {
            foreach (JsonNode? node in listing["slots"]!.AsArray())
            {
                if (string.Equals(node!["slot"]!.GetValue<string>(), slot, StringComparison.Ordinal))
                {
                    return (JsonObject)node!;
                }
            }

            return null;
        }

        private void CorruptSlotBytes(string slot)
        {
            string path = Path.Combine(_root, "saves", slot.Replace('/', Path.DirectorySeparatorChar) + ".ldsave");
            byte[] bytes = File.ReadAllBytes(path);
            bytes[^3] ^= 0xFF;
            File.WriteAllBytes(path, bytes);
        }

        private static GameEngine CreateEngine(string storageRoot)
        {
            GameEngine engine = CreateInitializedEngineWithoutStorage();
            engine.SetService(
                CoreServiceKeys.SaveStorage,
                (ISaveStorage)new DesktopSaveStorage(storageRoot));
            return engine;
        }

        private static void UseTurnBasedPacemaker(GameEngine engine)
        {
            engine.Pacemaker = new Ludots.Core.Engine.Pacemaker.TurnBasedPacemaker();
            engine.SimulationBudgetMsPerFrame = int.MaxValue;
            engine.SimulationMaxSlicesPerLogicFrame = 1000;
            engine.Start();
            ((Ludots.Core.Engine.Pacemaker.TurnBasedPacemaker)engine.Pacemaker).Step();
            engine.Tick(1f);
        }

        private static GameEngine CreateInitializedEngineWithoutStorage()
        {
            string? dir = TestContext.CurrentContext.TestDirectory;
            while (!string.IsNullOrEmpty(dir))
            {
                string gitPath = Path.Combine(dir, ".git");
                if ((Directory.Exists(gitPath) || File.Exists(gitPath)) &&
                    Directory.Exists(Path.Combine(dir, "src")) &&
                    Directory.Exists(Path.Combine(dir, "mods")))
                {
                    break;
                }

                dir = Directory.GetParent(dir)?.FullName;
            }

            var engine = new GameEngine();
            engine.InitializeWithConfigPipeline(
                RepoModPaths.ResolveExplicit(dir!, new[] { "LudotsCoreMod" }),
                Path.Combine(dir!, "assets"));
            engine.LoadStartupMap();
            return engine;
        }
    }

    internal static class SaveToolTestExtensions
    {
        internal static JsonObject ExecuteObject(this IAgentTool tool, JsonObject? args, AgentToolContext? context = null)
        {
            return (tool.Execute(args, context) as JsonObject)!;
        }
    }
}

using Ludots.AgentBridge.Tools;
using Ludots.Core.Diagnostics;

namespace Ludots.AgentBridge
{
    /// <summary>
    /// SSOT for built-in bridge tools: every concrete <see cref="IAgentTool"/> in this
    /// assembly is registered here. Clients (HTTP /tools, MCP, CLI, Inspector) all
    /// consume the live registry — never a parallel hand-written list.
    /// </summary>
    public static class BuiltinAgentTools
    {
        public static IReadOnlyList<string> ExpectedNames { get; } = new[]
        {
            "ludots.session.info",
            "ludots.time.get",
            "ludots.time.control",
            "ludots.camera.control",
            "ludots.logs.tail",
            "ludots.events.fire",
            "ludots.entities.query",
            "ludots.entities.pick",
            "ludots.spatial.query",
            "ludots.nav.project",
            "ludots.nav.findPath",
            "ludots.ui.tree",
            "ludots.ui.query",
            "ludots.ui.click",
            "ludots.gas.entity",
            "ludots.gas.diagnostics",
            "ludots.orders.inspect",
            "ludots.orders.issue",
            "ludots.input.state",
            "ludots.input.inject",
            "ludots.input.raw",
            "ludots.screenshot",
            "ludots.recording.start",
            "ludots.recording.stop",
            "ludots.graph.debug",
            "ludots.presenters.query",
            "ludots.presenters.desync",
            "ludots.presenters.screen",
        };

        public static void RegisterAll(
            AgentToolRegistry tools,
            AgentBridgeRuntime runtime,
            AgentTimeController time,
            RecordingController recording,
            AgentLogRingBackend logRing)
        {
            ArgumentNullException.ThrowIfNull(tools);
            ArgumentNullException.ThrowIfNull(runtime);
            ArgumentNullException.ThrowIfNull(time);
            ArgumentNullException.ThrowIfNull(recording);
            ArgumentNullException.ThrowIfNull(logRing);

            tools.Register(new SessionInfoTool(runtime));
            tools.Register(new TimeGetTool(time));
            tools.Register(new TimeControlTool(time));
            tools.Register(new CameraControlTool());
            tools.Register(new LogsTailTool(logRing));
            tools.Register(new EventsFireTool());
            tools.Register(new EntitiesQueryTool());
            tools.Register(new EntitiesPickTool());
            tools.Register(new SpatialQueryTool());
            tools.Register(new NavProjectTool());
            tools.Register(new NavFindPathTool());
            tools.Register(new UiTreeTool());
            tools.Register(new UiQueryTool());
            tools.Register(new UiClickTool());
            tools.Register(new GasEntityTool());
            tools.Register(new GasDiagnosticsTool());
            tools.Register(new OrdersInspectTool());
            tools.Register(new OrdersIssueTool());
            tools.Register(new InputStateTool(runtime));
            tools.Register(new InputInjectTool(runtime));
            tools.Register(new InputRawTool());
            tools.Register(new ScreenshotTool(runtime));
            tools.Register(new RecordingStartTool(recording, runtime));
            tools.Register(new RecordingStopTool(recording));
            tools.Register(new GraphDebugTool());
            tools.Register(new PresentersQueryTool());
            tools.Register(new PresentersDesyncTool());
            tools.Register(new PresentersScreenTool());
            tools.Register(new SaveSlotsTool());
            tools.Register(new SaveCaptureTool());
            tools.Register(new SaveWriteTool());
            tools.Register(new SaveReadTool());
            tools.Register(new SaveRestoreTool());
        }

        /// <summary>
        /// Install the log ring once when the bridge activates so
        /// <c>ludots.logs.tail</c> sees entries from that moment onward.
        /// </summary>
        public static void InstallLogRing(AgentLogRingBackend logRing)
        {
            ArgumentNullException.ThrowIfNull(logRing);
            Log.AddBackend(logRing);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using Arch.Core;
using Arch.Persistence;
using Arch.Relationships;
using Ludots.Core.Engine;
using Ludots.Core.Modding;
using MessagePack.Formatters;

namespace Ludots.Core.Persistence
{
    public static class LudotsPersistenceSerializerFactory
    {
        public static LudotsBinaryWorldSerializer Create(GameEngine engine)
        {
            if (engine == null) throw new ArgumentNullException(nameof(engine));

            return Create(engine.ModLoader);
        }

        public static LudotsBinaryWorldSerializer Create(ModLoader? modLoader)
        {
            Assembly[] componentAssemblies = CreateComponentAssemblySnapshot(modLoader);
            Assembly[] resolverAssemblies = CreateResolverAssemblySnapshot(componentAssemblies);
            var typeResolver = new AssemblySnapshotPersistenceTypeResolver(resolverAssemblies);
            (IMessagePackFormatter[] formatters, IReadOnlySet<Type> componentTypes) =
                LudotsCorePersistenceFormatters.CreateFormatterSet(componentAssemblies);

            IMessagePackFormatter[] serializerFormatters = formatters
                .Concat(new IMessagePackFormatter[] { new PersistenceTypeFormatter(typeResolver) })
                .ToArray();

            return new LudotsBinaryWorldSerializer(serializerFormatters, componentTypes);
        }

        private static Assembly[] CreateComponentAssemblySnapshot(ModLoader? modLoader)
        {
            var assemblies = new List<Assembly>(LudotsCorePersistenceFormatters.CreateCandidateAssemblySnapshot());

            if (modLoader != null)
            {
                assemblies.AddRange(modLoader.LoadedAssemblies);
            }

            return NormalizeAssemblies(assemblies);
        }

        private static Assembly[] CreateResolverAssemblySnapshot(IEnumerable<Assembly> componentAssemblies)
        {
            var assemblies = new List<Assembly>
            {
                typeof(World).Assembly,
                typeof(ArchBinarySerializer).Assembly,
                typeof(Relationship<>).Assembly,
                typeof(GameEngine).Assembly
            };
            assemblies.AddRange(componentAssemblies);
            return NormalizeAssemblies(assemblies);
        }

        private static Assembly[] NormalizeAssemblies(IEnumerable<Assembly> assemblies)
        {
            return assemblies
                .Where(assembly => assembly != null && !assembly.IsDynamic)
                .Distinct()
                .OrderBy(assembly => assembly.GetName().Name, StringComparer.Ordinal)
                .ThenBy(assembly => assembly.FullName, StringComparer.Ordinal)
                .ToArray();
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using Ludots.Platform.Abstractions;

namespace Ludots.Platform.Desktop
{
    /// <summary>
    /// File-system <see cref="ISaveStorage"/> for desktop hosts. Keys are repo-style relative paths
    /// ('saves/manual/slot.ldsave') rooted at the constructor directory; commits rename a fully
    /// written temp file over the final key so a crash never leaves a half-written slot behind.
    /// </summary>
    public sealed class DesktopSaveStorage : ISaveStorage
    {
        private readonly string _rootDirectory;

        public DesktopSaveStorage(string rootDirectory)
        {
            if (string.IsNullOrWhiteSpace(rootDirectory)) throw new ArgumentException("Root directory is empty.", nameof(rootDirectory));
            _rootDirectory = Path.GetFullPath(rootDirectory);
        }

        public string RootDirectory => _rootDirectory;

        public IReadOnlyList<string> ListFileKeys(string prefix)
        {
            if (prefix == null) throw new ArgumentNullException(nameof(prefix));

            string prefixPath = Resolve(prefix);
            if (!Directory.Exists(prefixPath))
            {
                return Array.Empty<string>();
            }

            var keys = new List<string>();
            foreach (string file in Directory.EnumerateFiles(prefixPath, "*", SearchOption.AllDirectories))
            {
                keys.Add(ToFileKey(file));
            }

            return keys;
        }

        public bool Exists(string key)
        {
            return File.Exists(Resolve(key));
        }

        public byte[] ReadAllBytes(string key)
        {
            return File.ReadAllBytes(Resolve(key));
        }

        public void WriteAllBytes(string key, byte[] bytes)
        {
            if (bytes == null) throw new ArgumentNullException(nameof(bytes));

            string path = Resolve(key);
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.WriteAllBytes(path, bytes);
        }

        public void CommitTempFile(string tempKey, string finalKey)
        {
            string tempPath = Resolve(tempKey);
            string finalPath = Resolve(finalKey);
            if (!File.Exists(tempPath))
            {
                throw new FileNotFoundException($"Temp file '{tempKey}' does not exist.");
            }

            Directory.CreateDirectory(Path.GetDirectoryName(finalPath)!);
            File.Move(tempPath, finalPath, overwrite: true);
        }

        public void Delete(string key)
        {
            File.Delete(Resolve(key));
        }

        private string Resolve(string key)
        {
            if (string.IsNullOrWhiteSpace(key))
            {
                throw new ArgumentException("Storage key is empty.", nameof(key));
            }

            string path = Path.GetFullPath(Path.Combine(_rootDirectory, key.Replace('/', Path.DirectorySeparatorChar)));
            if (!path.StartsWith(_rootDirectory + Path.DirectorySeparatorChar, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"Storage key '{key}' escapes the save root.");
            }

            return path;
        }

        private string ToFileKey(string absolutePath)
        {
            return Path.GetRelativePath(_rootDirectory, absolutePath).Replace(Path.DirectorySeparatorChar, '/');
        }
    }
